import itertools
from z3 import Solver, Bool, Or, Not, sat

def solve_ramsey():
    n = 22
    solver = Solver()
    solver.set(timeout=55000)

    x = {}
    for i in range(n):
        for j in range(i + 1, n):
            x[(i, j)] = Bool(f"x_{i}_{j}")

    # No red K5: at least one edge is blue (True)
    for clique in itertools.combinations(range(n), 5):
        edges = [x[(u, v)] if u < v else x[(v, u)] for u, v in itertools.combinations(clique, 2)]
        solver.add(Or(edges))

    # No blue K4: at least one edge is red (False)
    for clique in itertools.combinations(range(n), 4):
        edges = [Not(x[(u, v)] if u < v else x[(v, u)]) for u, v in itertools.combinations(clique, 2)]
        solver.add(Or(edges))

    print("Solving...")
    res = solver.check()
    print(f"Result: {res}")

    if res == sat:
        m = solver.model()
        solution = []
        for i in range(n):
            for j in range(i + 1, n):
                val = m[x[(i, j)]]
                solution.append(1 if val else 0)
        return solution
    else:
        return None

sol = solve_ramsey()
if sol:
    print("SAT")
    print(sol)
else:
    print("UNSAT")

def verify_solution(solution, n=22):
    import itertools

    # Reconstruct adjacency
    edges = {}
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = solution[idx]
            idx += 1

    # Check no red K5 (all edges 0)
    for clique in itertools.combinations(range(n), 5):
        all_red = True
        for u, v in itertools.combinations(clique, 2):
            if u > v:
                u, v = v, u
            if edges[(u,v)] != 0:
                all_red = False
                break
        if all_red:
            print(f"Found red K5: {clique}")
            return False

    # Check no blue K4 (all edges 1)
    for clique in itertools.combinations(range(n), 4):
        all_blue = True
        for u, v in itertools.combinations(clique, 2):
            if u > v:
                u, v = v, u
            if edges[(u,v)] != 1:
                all_blue = False
                break
        if all_blue:
            print(f"Found blue K4: {clique}")
            return False

    print("Solution verified: no red K5 and no blue K4")
    return True

